import { useRef, useEffect } from 'react'
import { useAssistantStore } from '@/app/store/assistantStore'
import { AssistantMessageList } from './AssistantMessageList'
import { AssistantComposer } from './AssistantComposer'

export function AssistantPanel() {
  const { messages } = useAssistantStore()
  const bottomRef = useRef<HTMLDivElement>(null)

  useEffect(() => {
    bottomRef.current?.scrollIntoView({ behavior: 'smooth' })
  }, [messages])

  return (
    <div className="flex flex-col h-full">
      <div className="flex-1 overflow-y-auto p-3">
        {messages.length === 0 ? (
          <div className="flex flex-col gap-2 pt-4">
            <p className="text-sm font-medium text-foreground">How can I help?</p>
            <p className="text-xs text-muted-foreground">
              I can help you manage objectives, suggest collaborators, summarize progress, and more.
            </p>
            <div className="flex flex-col gap-1.5 mt-2">
              {['Create a new objective', 'Summarize this project', 'Who should I assign to this?'].map(
                (chip) => (
                  <ContextChip key={chip} label={chip} />
                ),
              )}
            </div>
          </div>
        ) : (
          <AssistantMessageList messages={messages} />
        )}
        <div ref={bottomRef} />
      </div>
      <AssistantComposer />
    </div>
  )
}

function ContextChip({ label }: { label: string }) {
  const { setDraft } = useAssistantStore()
  return (
    <button
      onClick={() => setDraft(label)}
      className="text-left text-xs px-3 py-1.5 rounded-lg border border-border hover:border-accent/50 hover:bg-accent/5 transition-colors text-muted-foreground"
    >
      {label}
    </button>
  )
}
